"""Independent, conservative source audit; never converts a name hit into date proof."""
import json
import re
import sys
from collections import Counter
from pathlib import Path
import opencc

if __name__ != '__main__':
    raise RuntimeError('Run an explicit --batchNN mode; importing this audit script is unsafe.')

known_batch_flags = set(re.findall(r"'(--batch\d+)'\s+in\s+sys\.argv", Path(__file__).read_text(encoding='utf8')))
requested_batch_flags = [arg for arg in sys.argv[1:] if arg.startswith('--batch')]
if len(requested_batch_flags) != 1 or requested_batch_flags[0] not in known_batch_flags:
    raise SystemExit('Use one existing --batchNN mode; unsafe default rebuild and unknown batch modes are disabled.')

latest_batch_flag = max(known_batch_flags, key=lambda flag: int(flag[7:]))
current_review_path = Path(__file__).resolve().parents[1] / 'data/persons/reviews/review_4000_6999.jsonl'
if requested_batch_flags[0] != latest_batch_flag:
    if requested_batch_flags[0] == '--batch2' and current_review_path.exists():
        legacy_rows = [json.loads(line) for line in current_review_path.read_text(encoding='utf8').splitlines()]
        legacy_source = current_review_path.parents[3].parent / 'san11world-persons/data/persons/roster.json'
        legacy_roster = {r['id']: r for r in json.loads(legacy_source.read_text(encoding='utf8'))}
        assert len(legacy_rows) == 3000
        assert all(r['keys'] == legacy_roster[r['id']]['keys'] for r in legacy_rows)
        print(json.dumps(dict(legacy_batch2='validated_existing_incremental_ledger_without_replaying_old_mutations', latest_mode=latest_batch_flag, records=len(legacy_rows)), ensure_ascii=False))
        raise SystemExit(0)
    raise SystemExit('Historical batch replay disabled to preserve later adjudications; use ' + latest_batch_flag)
if not current_review_path.exists():
    raise SystemExit('Existing audit ledger is missing; recover its reviewed backup instead of rebuilding automatically.')

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT.parent / 'san11world-persons/data/persons'
CC = opencc.OpenCC('t2s')


def read_rows(path):
    return {r['id']: r for r in map(json.loads, path.read_text(encoding='utf8').splitlines())}


ledger = read_rows(ROOT / 'out/person_chronology/ledger.jsonl')
candidates = read_rows(ROOT / 'out/person_chronology/calibration_candidates.jsonl')
original = read_rows(ROOT / 'out/person_chronology/original_source_evidence.jsonl')
roster = {r['id']: r for r in json.loads((SOURCE / 'roster.json').read_text(encoding='utf8'))}
texts = {}


def text(path):
    path = Path(path)
    if path not in texts:
        texts[path] = CC.convert(path.read_text(encoding='utf8'))
    return texts[path]


def quote(book, phrase, note='Individually read and identity adjudicated'):
    path = SOURCE / '_cache/texts' / (book + '.txt')
    s = text(path)
    pos = s.find(phrase)
    assert pos >= 0, (book, phrase)
    return dict(source=str(path.resolve()), offset=pos, excerpt=phrase,
                normalization='OpenCC t2s', verification=note)


def chunk_quote(chunk, phrase):
    path=SOURCE/'_cache/chunks'/(chunk+'.txt');s=text(path);a=s.find(phrase)
    assert a>=0,(chunk,phrase)
    result=dict(source=str(path.resolve()),offset=a,excerpt=phrase,normalization='OpenCC t2s',
                verification='Individually read and identity adjudicated')
    if chunk.startswith('sl_'):
        result.update(source_tier='late_reconstruction',source_edition='明屠乔孙、项琳重编本；缓存卷首明示伪本，非崔鸿原著直传',requires_earlier_source_corroboration=True)
    return result


def date(year, evidence, inferred=False, **extra):
    if evidence.get('source_tier')=='late_reconstruction':
        extra.update(source_tier='late_reconstruction',strict_chronology_eligible=False,requires_earlier_source_corroboration=True)
    return dict(year=year, precision='inferred_year' if inferred else 'year',
                calendar='CE year; original Chinese calendar dates retained in evidence',
                source=evidence['source'], excerpt=evidence['excerpt'], **extra)


def note_once(record, value):
    if value not in record['unresolved']:
        record['unresolved'].append(value)


def delegated_sources(rows, ident, pairs, agent, scope):
    """Persist manually chosen quotations after the named delegate's actual read."""
    r=rows[ident];es=[]
    for chunk,q in pairs:
        e=chunk_quote(chunk,CC.convert(q));e.update(verification='Delegated_actual_original_text_personal_scope_read_authorized_parallel_audit',original_reader_agent='/root/chronology_4000_6999/'+agent,delegated_report_scope=scope)
        e['source_key']=next(k for k in r['keys'] if ':'+chunk+':' in k);es.append(e)
        if e not in r['evidence']:r['evidence'].append(e)
    return es


def finish_review_batch(rows, batch):
    assert len(rows)==3000
    for x in rows.values():assert x['keys']==roster[x['id']]['keys']
    dest=ROOT/'data/persons/reviews/review_4000_6999.jsonl'
    dest.write_text(''.join(json.dumps(rows[i],ensure_ascii=False)+'\n' for i in sorted(rows)),encoding='utf8')
    print(json.dumps(dict(batch=batch,records=len(rows),statuses=Counter(x['review_status'] for x in rows.values())),ensure_ascii=False));sys.exit()


