    dest.write_text(''.join(json.dumps(rows[i], ensure_ascii=False)+'\n' for i in sorted(rows)), encoding='utf8')
    print(json.dumps(dict(changed=[i for i, _, _ in work], count=len(work), statuses=Counter(r['review_status'] for r in rows.values())), ensure_ascii=False))
    sys.exit()

