    def checked8(ident, refs, note, death=None, all_keys=True, upper=None):
        r = rows[ident]
        ev = [chunk_quote(book, passage) for book, passage in refs]
        for e in ev:
            if e not in r['evidence']:
                r['evidence'].append(e)
        r.update(last_individual_review_batch='4000_6999_batch8', source_identities_all_adjudicated=all_keys,
                 identity_status='consulted_source_identity_checked' if all_keys else 'source_branches_require_identity_resolution',
                 review_status='primary_text_corroborated' if death and all_keys else 'source_checked_dates_unknown')
        if death:
            if all_keys:
                r['historical_death'] = date(death, ev[-1])
            else:
                r['historical_death'] = None
                r['adjudicated_branch_dates'] = dict(death=date(death, ev[-1]), scope=note)
        msg = '逐条实读本批所引段落，未载只指已查来源。'+note
        if msg not in r['unresolved']:
            r['unresolved'].append(msg)
        r['appearance_basis'] = '首次履职未确证，保留游戏登场估算；已证活动仅为在世/任职上界。'
        if upper:
            r['appearance_no_later_than'] = upper
        changed.append(ident)
        return r

