    def checked7(ident, refs, note, death=None, all_keys=True, upper=None):
        r = rows[ident]
        evidence = [chunk_quote(book, passage) for book, passage in refs]
        assert r['keys'] == roster[ident]['keys']
        for e in evidence:
            if e not in r['evidence']:
                r['evidence'].append(e)
        r.update(last_individual_review_batch='4000_6999_batch7',
                 source_identities_all_adjudicated=all_keys,
                 identity_status='consulted_source_identity_checked' if all_keys else 'source_branches_require_identity_resolution',
                 review_status=('primary_text_corroborated' if death else 'source_checked_dates_unknown') if all_keys else 'identity_conflict')
        r['appearance_basis'] = '未确认首次任官年份；保留游戏登场估算，不以首次检出自动推迟登场。'
        msg = '本批逐条实读所引本人段落；未载日期仅指已查引文，不宣称穷尽史籍。' + note
        if msg not in r['unresolved']:
            r['unresolved'].append(msg)
        if death:
            if all_keys:
                r['historical_death'] = date(death, evidence[-1])
            else:
                r['historical_death'] = None
                r['adjudicated_branch_dates'] = dict(death=date(death, evidence[-1]), scope=note)
        if upper:
            r['appearance_no_later_than'] = upper
        changed.append(ident)
        return r

