    def checked4(ident, passages, note='', all_keys=True, death=None, status=None):
        r = rows[ident]
        assert r['keys'] == roster[ident]['keys']
        for e in passages:
            if e not in r['evidence']:
                r['evidence'].append(e)
        r['source_identities_all_adjudicated'] = all_keys
        r['identity_status'] = 'consulted_source_identity_checked' if all_keys else 'source_branches_require_identity_resolution'
        r['review_status'] = status or ('primary_text_corroborated' if death else 'source_checked_dates_unknown')
        if death:
            d = date(death, passages[-1], original_calendar_note='所引原纪年按同号CE年映射；并非公历月日换算。')
            if all_keys:
                r['historical_death'] = d
            else:
                r['historical_death'] = None
                r['adjudicated_branch_dates'] = dict(identity=r['name']+'：已读主干，未含其他待裁分支', historical_birth=None, historical_death=d)
        msg = '本批逐条实读所引原段；未知生卒不取邻人年龄，不将回叙所在年当本人事件确年。'+note
        if msg not in r['unresolved']:
            r['unresolved'].append(msg)
        r['appearance_basis'] = '未证明首次任官之确年；原游戏登场继续作为估算。已证任职只能约束为不晚于该活动年。'
        r['last_individual_review_batch'] = '4000_6999_batch4'
        changed.append(ident)
        return r

