    dest = ROOT / 'data/persons/reviews/review_4000_6999.jsonl'
    rows = read_rows(dest)
    changed = []

    def review(ident, evidence, birth=None, death=None, all_keys=False, age=None, note=''):
        r = rows[ident]
        assert r['keys'] == roster[ident]['keys']
        if r.get('last_individual_review_batch') == '4000_6999_batch2':
            changed.append(ident)
            return r
        r['evidence'].extend(e for e in evidence if e not in r['evidence'])
        r['source_identities_all_adjudicated'] = all_keys
        r['identity_status'] = 'consulted_source_identity_checked' if all_keys else 'primary_biography_branch_checked_other_source_keys_pending'
        r['review_status'] = 'primary_text_corroborated' if birth is not None or death is not None else 'source_checked_dates_unknown'
        r['historical_birth'] = r['historical_death'] = None
        bd = date(birth, evidence[0], True, calculation=f'{death} - {age} + 1; Chinese nominal age', nominal_age=age) if birth is not None and age is not None else None
        dd = date(death, evidence[-1]) if death is not None else None
        if all_keys:
            r['historical_birth'], r['historical_death'] = bd, dd
        elif bd is not None or dd is not None:
            r['adjudicated_branch_dates'] = dict(identity=r['name'], historical_birth=bd, historical_death=dd,
                scope='Only the individually read biography/annal branch; remaining source keys are not adjudicated.')
        r['unresolved'] = [x for x in r['unresolved'] if x != 'Birth, death and first career year require individual primary-source adjudication; name retrieval is not validation.']
        r['unresolved'].append('本批实际读过所引原段；未穷尽全部史料。未载确年不以游戏设定、CBDB指数年或同段他人卒年补齐。' + note)
        if not all_keys:
            r['unresolved'].append('全部来源 keys 尚未逐支核清；日期仅限已读身份分支，整条日期修改继续 hold。')
        r['last_individual_review_batch'] = '4000_6999_batch2'
        changed.append(ident)
        return r

    def annal(phrase, year):
        e = quote('资治通鉴', phrase)
        s = text(e['source'])
        headings = list(re.finditer(r'[^\n]{0,50}（[^\n]*公元[^\n]*）', s[:e['offset']]))
        assert headings
        h = headings[-1]
        e['annal_heading'] = h.group().strip()
        e['annal_heading_offset'] = h.start()
        e['annal_ce_year'] = year
        e['calendar_note'] = 'Original annal year is mapped to its conventional CE year; lunar dates are not converted to Gregorian dates.'
        return e

