rows = {}
for ident in range(4000, 7000):
    person, audit, cand = roster[ident], ledger[ident], candidates[ident]
    r = dict(id=ident, keys=person['keys'], name=person['name_full'],
             historical_birth=None, historical_death=None, proposed_appear=None,
             appearance_basis='Existing game appearance is unverified; no proposed postponement from first mention in a truncated source window.',
             duplicate_of=None, identity_status='not_individually_adjudicated', evidence=[],
             review_status='needs_further_research',
             unresolved=['Birth, death and first career year require individual primary-source adjudication; name retrieval is not validation.'],
             current_game=audit['current_game'])
    for chunk in audit.get('source_chunks', []):
        path = Path(chunk['path'])
        if not path.exists():
            continue
        s = text(path)
        name = CC.convert(chunk['key'].split(':')[-1])
        pos = s.find(name)
        if pos >= 0:
            r['evidence'].append(dict(source=str(path.resolve()), source_key=chunk['key'], offset=pos,
                excerpt=s[max(0,pos-65):pos+len(name)+100], normalization='OpenCC t2s',
                verification='automated_literal_name_retrieval_only_not_identity_or_dates_verified'))
        if len(r['evidence']) >= 2:
            break
    db = original[ident].get('cbdb_originals', [])
    if db:
        r['cbdb_original_records'] = db
        r['unresolved'].append('CBDB index year is not an activity year; CBDB dates/age require underlying cited-source verification.')
    if audit.get('issues'):
        r['source_audit_flags'] = audit['issues']
    rows[ident] = r

