def life(ident, death, age, phrase, death_phrase=None, confidence='year'):
    r = rows[ident]
    q = quote('晋书', phrase)
    r['evidence'].append(q)
    if death_phrase:
        dq = quote('资治通鉴', death_phrase)
        r['evidence'].append(dq)
    else:
        dq = q
    r['historical_death'] = date(death, dq)
    r['historical_death']['precision'] = confidence
    r['historical_birth'] = date(death-age+1, q, True,
        inference=f'{death} - {age} + 1; assumes Chinese nominal age, not an explicit birth date',
        depends_on_death_year=death)
    r['identity_status'] = 'biography_identity_adjudicated'
    r['review_status'] = 'primary_text_corroborated'
    r['unresolved'] = ['Birth year is inferred from nominal age; month/day and historical first office year unknown in consulted passages.']
    r['proposed_appear'] = death-age+17
    r['appearance_basis'] = 'Game calibration convention inferred birth year + 16; not a historically attested first appointment.'


