def duplicate(ident, canonical, explanation, primary=None):
    r=rows[ident];r['duplicate_of']=canonical;r['review_status']='duplicate'
    r['identity_status']='same_historical_person_as_canonical'
    r['duplicate_evidence']=explanation
    r['unresolved']=['Merge source keys into canonical record before applying dates; do not retain fabricated second lifespan.']
    if primary:
        r['evidence'].append(quote('晋书',primary))
    for field in ['historical_birth','historical_death','proposed_appear','appearance_basis']:
        r[field]=rows[canonical][field]


